    while (n--) {
        solve();
    }
}

#include <bits/stdc++.h>

using namespace std;
using ll = long long;

void solve() {
    priority_queue<pair<int, int>> q;
    int n;
    cin >> n;
    map<int, int> v;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        v[x]++;
    }
    for (auto [x, y] : v) {
        q.push({y, x});
    }
    int sz = n;
    while (q.size() >= 2) {
        auto [cnt1, x1] = q.top();
        q.pop();
        auto [cnt2, x2] = q.top();
        q.pop();
        cnt1--;
        cnt2--;
        sz -= 2;
        if (cnt1) {
            q.push({cnt1, x1});
        }
        if (cnt2) {
            q.push({cnt2, x2});
        }
    }
    cout << sz << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr); cout.tie(nullptr);
    int n;
    cin >> n;
    while (n--) {
        solve();
    }
}

#include <bits/stdc++.h>
using namespace std;

void placeLeft(vector<int> &q, bool minimize) {
  set<int> left;
  for (int i = 1; i <= (int) q.size(); i++) {
    left.insert(i);
  }
  for (int i : q) {
    if (i != -1) {
      left.erase(i);
    }
  }
  int lastPlaced = -1;
  for (int &i : q) {
    if (i == -1) {
      set<int>::const_iterator it;
      if (minimize) {
        it = left.begin();
      } else {
        it = --left.lower_bound(lastPlaced);
      }
      i = *it;
      left.erase(it);
    } else {
      lastPlaced = i;
    }
  }
}

void solve() {
  int n;
  cin >> n;
  vector<int> q(n);
  for (int i = 0; i < n; i++) {
    cin >> q[i];
  }

  vector<int> res1(n, -1), res2(n, -1);
  for (int i = 0, lastPlaced = -1; i < n; lastPlaced = q[i], i++) {
    if (lastPlaced != q[i]) {
      res1[i] = q[i];
      res2[i] = q[i];
    }
  }
  placeLeft(res1, true);
  placeLeft(res2, false);
  for (int x : res1) {
    cout << x << " ";
  }
  cout << "\n";
  for (int x : res2) {
    cout << x << " ";
  }
  cout << "\n";
}

int main() {
  int tests;
  cin >> tests;
  while (tests-- > 0) {
    solve();
  }
  return 0;
}

#include <bits/stdc++.h>
using namespace std;

bool isLeftArrow(int r, int c) {
  return (r + c) % 2 == 0;
}

bool isRightArrow(int r, int c) {
  return (r + c) % 2 == 1;
}

int calcDist(int r1, int c1, int r2, int c2) {
  if (r1 - c1 == r2 - c2) {
    return isRightArrow(r1, c1) ? 0 : r2 - r1;
  }
  r2 -= r1 - 1;
  c2 -= c1 - 1;
  if (isLeftArrow(r1, c1)) {
    return (r2 - c2) / 2;
  } else {
    return (r2 - c2 + 1) / 2;
  }
}

void solve() {
  int n;
  cin >> n;
  vector<int> r(n);
  vector<int> c(n);
  for (int i = 0; i < n; i++) {
    cin >> r[i];
  }
  for (int i = 0; i < n; i++) {
    cin >> c[i];
  }
  vector<pair<int, int>> pts;
  for (int i = 0; i < n; i++) {
    pts.emplace_back(r[i], c[i]);
  }
  sort(pts.begin(), pts.end());
  int curR = 1, curC = 1;
  int res = 0;
  for (auto[nextR, nextC] : pts) {
    res += calcDist(curR, curC, nextR, nextC);
    curR = nextR;
    curC = nextC;
  }
  cout << res << "\n";
}

int main() {
  int tests;
  cin >> tests;
  while (tests-- > 0) {
    solve();
  }
  return 0;
}

#include <bits/stdc++.h>
using namespace std;

int distinct(string s) {
  sort(s.begin(), s.end());
  return unique(s.begin(), s.end()) - s.begin();
}

string filter(const string &s, char c) {
  string t;
  bool foundFirst = false;
  for (char a : s) {
    if (a != c && foundFirst) {
      t += a;
    } else if (a == c) {
      foundFirst = true;
    }
  }
  return t;
}

void solve() {
  string s;
  cin >> s;
  int m = distinct(s);
  unordered_set<char> used(s.begin(), s.end());
  string t;
  while (m > 0) {
    char maxC = -1;
    for (char c : used) {
      if (distinct(filter(s, c)) == m - 1) {
        maxC = max(maxC, c);
      }
    }
    t += maxC;
    s = filter(s, maxC);
    used.erase(maxC);
    m--;
  }
  cout << t << "\n";
}

int main() {
  int tests;
  cin >> tests;
  while (tests-- > 0) {
    solve();
  }
  return 0;
}
